# Freeze the USGS snapshot into engine/quakes.js (compact) + data/manifest.json. Every claim in the video reads from these.
# Source: USGS ANSS ComCat via the FDSN event service (US public domain); land outlines: Natural Earth 1:110m (public domain).
import json, hashlib, os, datetime, collections
HERE = os.path.dirname(os.path.abspath(__file__)); DATA = os.path.join(HERE, "..", "data")
raw = os.path.join(DATA, "raw", "usgs_2025_m45.geojson"); land = os.path.join(DATA, "raw", "ne_110m_land.geojson")
QUERY = "https://earthquake.usgs.gov/fdsnws/event/1/query?format=geojson&starttime=2025-01-01T00:00:00Z&endtime=2026-01-01T00:00:00Z&minmagnitude=4.5&eventtype=earthquake&orderby=time-asc"
gj = json.load(open(raw, encoding="utf-8")); feats = gj["features"]
t0 = int(datetime.datetime(2025, 1, 1, tzinfo=datetime.timezone.utc).timestamp() * 1000); t1 = int(datetime.datetime(2026, 1, 1, tzinfo=datetime.timezone.utc).timestamp() * 1000)
ev, skipped, ids = [], [], set()
for f in feats:
    p, g = f["properties"], f.get("geometry")
    assert p["type"] == "earthquake" and p["mag"] is not None and p["mag"] >= 4.5 and t0 <= p["time"] < t1, f["id"]
    assert f["id"] not in ids; ids.add(f["id"])
    if not g or g.get("coordinates") is None: skipped.append(f["id"]); continue
    lon, lat, dep = g["coordinates"]
    ev.append([p["time"], round(lon, 3), round(lat, 3), round(dep if dep is not None else 0, 1), round(p["mag"], 2), p.get("magType") or "", f["id"], p.get("place") or ""])
ev.sort(key=lambda e: (e[0], e[6]))
days = collections.Counter(datetime.datetime.fromtimestamp(e[0] / 1000, datetime.timezone.utc).strftime("%Y-%m-%d") for e in ev)
big = max(ev, key=lambda e: e[4]); busiest = max(days.items(), key=lambda kv: (kv[1], kv[0]))
mags = collections.Counter("M≥%d" % k for e in ev for k in (5, 6, 7, 8) if e[4] >= k)
landgj = json.load(open(land, encoding="utf-8"))
rings = []
for f in landgj["features"]:
    g = f["geometry"]; polys = [g["coordinates"]] if g["type"] == "Polygon" else g["coordinates"]
    for poly in polys: rings.append([[round(x, 2), round(y, 2)] for x, y in poly[0]])
man = {"source": "USGS ANSS Comprehensive Earthquake Catalog (ComCat), FDSN event web service", "query": QUERY,
       "downloaded_utc": open(os.path.join(DATA, "raw", "downloaded_utc.txt")).read().strip(),
       "sha256_raw": hashlib.sha256(open(raw, "rb").read()).hexdigest(), "features": len(feats), "located": len(ev), "unlocated": skipped,
       "largest": {"id": big[6], "time_utc": datetime.datetime.fromtimestamp(big[0] / 1000, datetime.timezone.utc).isoformat(), "mag": big[4], "magType": big[5], "place": big[7], "depth_km": big[3]},
       "busiest_utc_day": {"day": busiest[0], "events": busiest[1]}, "counts": dict(mags),
       "land": "Natural Earth 1:110m land (public domain)", "land_sha256": hashlib.sha256(open(land, "rb").read()).hexdigest()}
json.dump(man, open(os.path.join(DATA, "manifest.json"), "w", encoding="utf-8"), indent=2, ensure_ascii=False)
open(os.path.join(HERE, "quakes.js"), "w", encoding="utf-8").write("// Generated by prepare_data.py from the frozen USGS snapshot; see data/manifest.json\n(function(root){root.QUAKES=" + json.dumps({"t0": t0, "t1": t1, "events": ev, "manifest": man}, separators=(",", ":"), ensure_ascii=False) + ";root.LAND=" + json.dumps(rings, separators=(",", ":")) + ";if(typeof module!=='undefined')module.exports={QUAKES:root.QUAKES,LAND:root.LAND};})(typeof window!=='undefined'?window:globalThis);\n")
print(json.dumps({k: man[k] for k in ("features", "located", "largest", "busiest_utc_day", "counts")}, ensure_ascii=False, indent=1)); print("unlocated:", len(skipped), "land rings:", len(rings))
